# frozen_string_literal: true

# Generated by Descant: acceptance tests.
require "rails_helper"

RSpec.describe Invoices::BulkDeletionService do
  let(:company) { create(:company) }
  let(:client) { create(:client, company:) }

  def money_and_children_of(invoice)
    invoice.reload
    {
      line_item_ids: invoice.invoice_line_items.pluck(:id),
      tax_ids: invoice.invoice_taxes.pluck(:id),
      amount: invoice.amount,
      tax: invoice.tax,
      discount: invoice.discount,
      outstanding_amount: invoice.outstanding_amount
    }
  end

  def create_paid_invoice_with_children
    paid = create(:invoice, company:, client:, amount_due: 300)
    create(:invoice_line_item, invoice: paid)
    create(:invoice_tax, invoice: paid)
    create(:payment, invoice: paid, amount: 300)
    paid
  end

  # A paid invoice destroys its line items and taxes before its payment refuses
  # the destroy, so only the per-invoice savepoint keeps those rows.
  it "deletes the payment-free invoice, returns only the paid invoice id and leaves the paid invoice's children and totals untouched" do
    deletable = create(:invoice, company:, client:)
    paid = create_paid_invoice_with_children
    baseline = money_and_children_of(paid)
    expect(baseline[:line_item_ids].size).to eq(1)
    expect(baseline[:tax_ids].size).to eq(1)

    undeletable_ids = described_class.process(company.invoices.where(id: [deletable.id, paid.id]))

    expect(undeletable_ids).to eq([paid.id])
    expect(Invoice.exists?(deletable.id)).to be(false)
    expect(money_and_children_of(paid)).to eq(baseline)
  end

  # With the refused invoice first, a missing savepoint would leave its children
  # deleted while the rest of the batch still commits.
  it "keeps a paid invoice whole when it is refused before a deletable invoice later in the same batch" do
    paid = create_paid_invoice_with_children
    deletable = create(:invoice, company:, client:)
    baseline = money_and_children_of(paid)

    undeletable_ids = described_class.process(company.invoices.where(id: [paid.id, deletable.id]).order(:id))

    expect(undeletable_ids).to eq([paid.id])
    expect(Invoice.exists?(deletable.id)).to be(false)
    expect(money_and_children_of(paid)).to eq(baseline)
  end

  # One fence for the whole batch means a handoff refuses every invoice, and the
  # error must reach the controller unrescued so it still answers 503.
  it "raises OwnershipMoving during a handoff and deletes none of a mixed batch or its children" do
    deletable = create(:invoice, company:, client:)
    create(:invoice_line_item, invoice: deletable)
    create(:invoice_tax, invoice: deletable)
    paid = create_paid_invoice_with_children
    ids = [deletable.id, paid.id]
    line_item_ids = InvoiceLineItem.where(invoice_id: ids).pluck(:id)
    tax_ids = InvoiceTax.where(invoice_id: ids).pluck(:id)
    # One line item and one tax were created for each of the two invoices.
    expect(line_item_ids.size).to eq(2)
    expect(tax_ids.size).to eq(2)
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    expect {
      described_class.process(company.invoices.where(id: ids))
    }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)

    expect(Invoice.where(id: ids).count).to eq(2)
    expect(InvoiceLineItem.where(invoice_id: ids).pluck(:id)).to match_array(line_item_ids)
    expect(InvoiceTax.where(invoice_id: ids).pluck(:id)).to match_array(tax_ids)
  end

  # The controller passes current_company.invoices.where(id: ...); an id that
  # belongs to another company is neither deleted nor reported.
  it "deletes only the invoices in the company-scoped relation it is given" do
    own_invoice = create(:invoice, company:, client:)
    kept_own_invoice = create(:invoice, company:, client:)
    foreign_invoice = create(:invoice_with_invoice_line_items)
    expect(foreign_invoice.company_id).not_to eq(company.id)
    foreign_line_item_ids = InvoiceLineItem.where(invoice_id: foreign_invoice.id).order(:id).pluck(:id)
    expect(foreign_line_item_ids).not_to be_empty

    undeletable_ids = described_class.process(company.invoices.where(id: [own_invoice.id, foreign_invoice.id]))

    expect(undeletable_ids).to eq([])
    expect(Invoice.exists?(own_invoice.id)).to be(false)
    expect(Invoice.exists?(kept_own_invoice.id)).to be(true)
    expect(Invoice.exists?(foreign_invoice.id)).to be(true)
    expect(InvoiceLineItem.where(invoice_id: foreign_invoice.id).order(:id).pluck(:id)).to eq(foreign_line_item_ids)
  end

  it "returns no ids and deletes every invoice in a payment-free batch, and a repeat call deletes nothing more" do
    invoices = create_list(:invoice, 3, company:, client:)
    bystander = create(:invoice, company:, client:)
    ids = invoices.map(&:id)

    expect(described_class.process(company.invoices.where(id: ids))).to eq([])
    expect(Invoice.where(id: ids)).to be_empty

    expect(described_class.process(company.invoices.where(id: ids))).to eq([])
    expect(Invoice.exists?(bystander.id)).to be(true)
  end

  it "returns an empty list for an empty invoice relation" do
    untouched = create(:invoice, company:, client:)

    expect(described_class.process(company.invoices.where(id: []))).to eq([])
    expect(Invoice.exists?(untouched.id)).to be(true)
  end
end
